            resources.append((p[0], p[1]))

    def md(a, b, c):
        return abs(a - b) + abs(c - sy)

    if resources:
        tx, ty = resources[0]
        bestd = abs(tx - sx) + abs(ty - sy)
        for x, y in resources[1:]:
            d = abs(x - sx) + abs(y - sy)
            if d < bestd:
                tx, ty, bestd = x, y, d
        dx = 0 if tx == sx else (1 if tx > sx else -1)
        dy = 0 if ty == sy else (1 if ty > sy else -1)
        cand = [(dx, 0), (0, dy), (dx, dy), (-dx, 0), (0, -dy)]
    else:
