        dy = 1 if sy <= oy else -1
        cand = [(dx, 0), (0, dy), (dx, dy), (-dx, 0), (0, -dy), (0, 0)]

    best = (0, 0)
    best_score = None
    for dx, dy in cand:
        nx, ny = sx + dx, sy + dy
        if nx < 0 or ny < 0 or nx >= w or ny >= h or (nx, ny) in obstacles:
            continue
        score = 0
        if resources:
            d = min(abs(nx - x) + abs(ny - y) for x, y in resources)
            score -= d * 10
        score -= abs(nx - ox) + abs(ny - oy)
        if (nx, ny) in observation.get("self_path", []):
            score -= 3
        if (nx, ny) in observation.get("opponent_path", []):
            score -= 2
        if best_score is None or score > best_score:
            best = (dx, dy)
            best_score = score
    return [int(best[0]), int(best[1])]

